                pat[k]=v
            if good:
                # Fill unknown phase(s) from repeated pattern, falling back to original 0 only if not inferable.
                if len(pat)==p:
                    return [[pat[i%p]]*w for i in range(h)]
                # Can't determine an unobserved phase; try a larger period.
        # fallback preserve known rows
        return [([vals[i]]*w if vals[i] else [0]*w) for i in range(h)]
    # Complete diagonal bands: color depends only on wrapped column-row offset.
    known = [(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    for p in range(1, max(h,w)+1):
        pat={}; good=True
        for r,c,v in known:
            k=(c-r)%p
            if k in pat and pat[k]!=v:
