program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Horizontal bands are a masked one-dimensional periodic sequence.
    if all(len(set(row)) == 1 for row in grid):
        vals = [row[0] for row in grid]
        known = {i: v for i, v in enumerate(vals) if v != 0}
        if not known:
            return [row[:] for row in grid]
        for period in range(1, h + 1):
            pattern = {}
            for i, value in known.items():
                phase = i % period
                if phase in pattern and pattern[phase] != value:
                    break
                pattern[phase] = value
            else:
                if len(pattern) == period:
                    return [[pattern[i % period]] * w for i in range(h)]
        return [row[:] for row in grid]

    # Otherwise complete wrapped diagonal bands, with color determined by c-r.
    known = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    for period in range(1, max(h, w) + 1):
        pattern = {}
        for r, c, value in known:
            phase = (c - r) % period
            if phase in pattern and pattern[phase] != value:
                break
            pattern[phase] = value
        else:
            if len(pattern) == period:
                return [[pattern[(c - r) % period] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
